 a=np.array(path['start_mm']);b=np.array(path['end_mm']);c=np.array(center);axis=b-a;length=float(np.linalg.norm(axis));u=axis/length;t=float(np.clip((c-a)@u,0,length));q=a+u*t
 vertical=bool(np.linalg.norm(u[:2])<1e-12);xy=float(np.linalg.norm(c[:2]-q[:2]));dz=float(abs(c[2]-q[2]));required=math.hypot(xy+radius,dz);available=path['continuous_clearance_lower_bound_mm'];passed=vertical and required+1e-9<=available and path['clearance_passed']
 return {'section_disk_center_mm':c.tolist(),'section_disk_radius_mm':radius,'certified_stem_path_id':path['path_id'],'stem_start_mm':a.tolist(),'stem_end_mm':b.tolist(),'nearest_certified_stem_axis_point_mm':q.tolist(),'vertical_offset_from_stem_axis_segment_mm':dz,'horizontal_offset_mm':xy,'whole_disk_enclosing_ball_radius_mm':required,'certified_stem_capsule_radius_mm':available,'containment_margin_mm':available-required,'passed':passed,'proof':'The certified stem capsule contains a material ball of its certified radius at every point of its complete vertical axis segment. At the closest such axis point, every point of this exact-z horizontal radius0.4 disk is at most hypot(horizontal-offset+0.4,vertical-offset) away. Full-disk containment gives direct material overlap with the already certified column-to-four-shell-branch graph.'}
