 out=HERE/'root_evidence';support=json.load(gzip.open(out/'root_support_details.json.gz','rt'));loss=json.load(gzip.open(out/'root_loss_details.json.gz','rt'));paths={p['root_index']:p for p in support['paths']if p['name']=='column_stem'};rows=[]
 for r in loss['component_records']:
  c=r['source_head_xy_mm']+[r['strict_original_record']['z_mm']];q=check_disk(c,paths[r['source_root_index']]);q.update(component_record_index=r['component_record_index'],component_key=[r['strict_original_record'][k]for k in['grid','z_mm','component']],source_root_name=r['source_root_name']);rows.append(q)
 # Deliberately unlinked disk and a failed source certificate must be rejected.
 good=loss['component_records'][0];p=paths[good['source_root_index']];c=good['source_head_xy_mm']+[good['strict_original_record']['z_mm']];far=c.copy();far[0]+=2;bad=dict(p,clearance_passed=False);neg=[{'name':'unlinked_disk_shifted_2mm','expected_passed':False,'witness':check_disk(far,p)},{'name':'failed_source_root_certificate','expected_passed':False,'witness':check_disk(c,bad)}]
 for n in neg:n['passed']=n['witness']['passed']==n['expected_passed']
 gzipjson(out/'root_section_connection_details.json.gz',{'stl_sha256':support['stl_sha256'],'disk_connections':rows,'negative_controls':neg})
 report={'passed':len(rows)==98 and all(r['passed']for r in rows)and all(n['passed']for n in neg),'stl_sha256':support['stl_sha256'],'exact_failed_component_disk_connections':len(rows),'required_disk_radius_mm':.4,'minimum_certified_stem_capsule_radius_mm':min(r['certified_stem_capsule_radius_mm']for r in rows),'maximum_required_enclosing_ball_radius_mm':max(r['whole_disk_enclosing_ball_radius_mm']for r in rows),'maximum_section_plane_gap_from_stem_axis_mm':max(r['vertical_offset_from_stem_axis_segment_mm']for r in rows),'minimum_disk_containment_margin_mm':min(r['containment_margin_mm']for r in rows),'failed_connections':[r for r in rows if not r['passed']],'negative_controls_passed':all(n['passed']for n in neg),'negative_control_count':len(neg),'source_support_report_sha256':sha(out/'root_support_report.json'),'source_loss_report_sha256':sha(out/'root_loss_report.json'),'source_support_details_sha256':sha(out/'root_support_details.json.gz'),'source_loss_details_sha256':sha(out/'root_loss_details.json.gz'),'validator_sha256':sha(Path(__file__)),'detail_file':'root_section_connection_details.json.gz','detail_sha256':sha(out/'root_section_connection_details.json.gz'),'strict_morphology_passed':False};writejson(out/'root_section_connection_report.json',report);print(json.dumps(report,indent=2));return report
